import type { CollectionInput, InstitutionInput, TrialInput } from "@/lib/schema";

/**
 * Research funding programmes the November 2026 gap census (docs/proposals/gap-census-2026-11.md, type
 * `grants-programmes`) found missing: the nine cancer programmes of the US Defense Department's Congressionally
 * Directed Medical Research Programs (CDMRP) and the CDMRP itself, NCI Cancer Moonshot networks, the ARPA-H 1-CURE
 * programme, five Cancer Grand Challenges teams, and Horizon Europe Cancer Mission projects with the Mission itself.
 *
 * How they are modelled. The corpus already holds funders and funded programmes as institution records (Cancer
 * Grand Challenges and CPRIT are `institution` records of type consortium and government), and holds data
 * programmes as collections (HTAN, TCGA/GDC, the Imaging Data Commons). This file follows that: a funding body or
 * a funded research network is an institution (government for a programme run by a government office, consortium
 * for a multi-institution team or network), a data programme is a collection, and an EU project that is itself a
 * registered clinical trial is a trial record, as the census asks. Glossary terms were not used because a funding
 * programme is not a word a reader looks up. An institution needs a place: a CDMRP programme sits at Fort Detrick,
 * where the CDMRP office is; an NCI network without a named coordinating centre sits at NCI in Bethesda (stated in
 * each record's notes); a team or project sits at its lead or coordinating institution.
 *
 * Every figure was read on 4 November 2026 from the linked official page, fetched with curl and stripped of HTML:
 * cdmrp.health.mil programme pages, cancer.gov and its sub-sites, arpa-h.gov, cancergrandchallenges.org, the
 * CORDIS project records (XML), and the ClinicalTrials.gov v2 API. Nothing is from memory.
 */

const asOf = "2026-11-04";

type I = Omit<InstitutionInput, "kind" | "asOf">;
const i = (x: I): InstitutionInput => ({ kind: "institution", asOf, ...x, tags: ["research-funding", ...(x.tags ?? [])] });

type C = Omit<CollectionInput, "kind" | "asOf">;
const c = (x: C): CollectionInput => ({ kind: "collection", asOf, ...x, tags: ["research-funding", "data", ...(x.tags ?? [])] });

type T = Omit<TrialInput, "kind" | "asOf">;
const t = (x: T): TrialInput => ({ kind: "trial", asOf, ...x });

